'use strict';
(function(root){
 const E=root.PortoBuffo,dict={};
 const add=(it,en)=>{dict[it]=en;};
 const map=(source,target)=>source.forEach((value,i)=>add(value,target[i]));
 map(E.places,["Baker's Square","Lantern Pier","Ice Cream Festival","Baron's Theatre","Parcel Warehouse","Cloud Lighthouse"]);
 map(E.vehicles,['Bicycle','Motorbike','Patrol car','Sports car','Truck','Helicopter']);
 map(E.stations,['Neighbourhood office','Radio room','Colour laboratory','Detective archive','Parcel workshop','Operations centre']);
 map(E.ranks,['Trainee','Neighbourhood officer','Senior officer','Inspector','Commissioner','Chief detective','Hero of Porto Buffo']);
 map(Object.values(E.items).map(x=>x[0]),['Brass key','Red','Yellow','Blue','Orange','Purple','Green','Light cloth','Rope','Kite']);
 const stories=[
 ['The locked-up recipe','Riddle and key',"Ada has lost her doughnut recipe. Little thief Gino locked it in his chest. Berto at the pier has a key… and a riddle!","First day as a police officer. First mystery. I was hoping to start with a doughnut!","Open Gino's chest and return the recipe to Ada.","The recipe is inside! Gino gives it back. ‘I wanted to make square doughnuts!’ A crooked crown is drawn on the paper… someone hired him.",["Good manners will not open a locked chest. Who might have a key?","Talk to Berto at the pier and ask about the key.","The riddle's answer is a key. Once you have it, use it on the chest in the square."]],
 ["The thief's serenade",'Musical sequence',"Nino stole the bells to play for Baron Topsy-Turvy. He hid them behind a magical organ. Someone left the sheet music in the square.","A thief who leaves sheet music? At last, a case with a good soundtrack.","Find the melody and open Nino's organ.","The melody opens the hiding place! Nino returns the bells. ‘The Baron promised me a bicycle orchestra!’ His letter has the same crooked crown.",["The organ's symbols look like the pictures on a sign in the square.","Look at the sheet music in the square: read the sequence from left to right.","Play Sun, Moon, Sun, Star. If you get it wrong, try again. You will not lose anything."]],
 ['The ice cream that would not melt','Mixing colours',"The Cone Gang locked the ice cream cart with a coloured lock. It wants the colour of an orange. The bottles are around the festival and the square.","An orange-flavoured lock. I hope it doesn't ask for the bill too!","Make the right colour and unlock the ice cream machine.","Red and yellow make orange! The cart is free and the children get their ice cream. The gang says: ‘The Baron wanted all the ice cream for his private party!’",["There is an orange drawn on the machine. Which two colours could paint it?","Use Take to collect the bottles. Click two colours in your pockets to mix them.","Mix Red and Yellow to make Orange, then use it on the machine. You can reuse the bottles."]],
 ['Three masks, one crown','Two-clue deduction',"The theatre's crown has vanished. Three actors in masks are suspects. There are muddy tracks at the pier and a scrap of cloth in the theatre.","Three suspects and just one crown. I hope none of them is called ‘It Wasn't Me’.","Compare both clues and choose the right suspect.","Only the Pirate has red gloves AND muddy boots! He returns the crown and admits: ‘The Baron wanted to be king of the port. I thought it was a play!’",["One clue is not enough: look at the tracks at the pier and the cloth in the theatre.","We need someone with red gloves AND muddy boots.","The Jester has clean boots. The Wizard has blue gloves. The Pirate matches both clues."]],
 ['The upside-down post','Sorting and comparing',"Professor Muddle turned the parcel machine backwards. Ada is waiting for flour, but she received a hat with three feathers!","A hat in the cake? I should have read the recipe more carefully.","Sort the parcels from smallest to largest.","The machine works again! Parcels and flour reach the right people. The Professor hands over the Baron's last order: ‘Hide the lighthouse with a cloud!’",["The machine has three spaces and three parcels of different sizes.","Look at the sign at the festival: the arrow goes from small to large.","Move the small parcel left, then the medium one. Confirm when you see small, medium, large."]],
 ['The Baron and the stubborn cloud','Crafting and final riddle',"Baron Topsy-Turvy covered the lighthouse with a cloud. The boats cannot find the port! We need cloth from the warehouse, a rope and an idea that can fly.","My first case was a recipe. Now I have to arrest… a cloud? That wasn't in the handbook.","Build something that flies and move the cloud away from the boats.","The kite takes the cloud out to the open sea. The lighthouse shines! The Baron admits: ‘I wanted to be important. I only made a mess.’ He will help repair the port. Pippo becomes the Hero of Porto Buffo!",["Look at the machine and visit the warehouse. What can you make with cloth and rope?","Take the Cloth and Rope. Select one item in your pockets, then the other to combine them.","Use the Kite on the machine. It answers the wind's riddle. Then choose Open sea to move the cloud away from the boats."]]
 ];
 E.cases.forEach((c,i)=>{['title','type','brief','intro','goal','ending'].forEach((field,j)=>add(c[field],stories[i][j]));map(c.hints,stories[i][6]);});
 const props=[
 [['Ada the baker',"Ada has flour on her nose. I think it is her baker's badge."],["Gino's chest","A sturdy chest with a lock. It says: ‘Absolutely no recipes inside’. Very suspicious."],['Berto the keeper',"Berto guards the port's keys. And perhaps all its worst jokes."]],
 [['Berto',"Berto is covering his ears. This must be a very special serenade."],['Symbol organ','Three keys: Sun, Moon and Star. Each plays a different note.'],['Forgotten sheet music','Sun, Moon, Sun, Star. Nino drew the melody instead of writing notes.'],['Ada','Ada keeps the beat with her rolling pin.']],
 [['Ice cream machine',"The lock has a picture of an orange. It wants the colour, not a real fruit."],['Yellow bottle',"Yellow like the sun. The label says: ‘Not lemonade’. What a shame."],['Blue bottle',"Blue like the sea. Better not drink it!"],['Red bottle',"Red like a tomato. Useful for making a new colour."],['Ada','Ada collects colours to decorate cakes.']],
 [['The three masks','Three costumes: Wizard with blue gloves and muddy boots; Jester with red gloves and clean boots; Pirate with red gloves and muddy boots.'],['Scrap of cloth',"A piece of a RED glove was left near the crown's display case."],['Muddy footprints','Whoever took the crown crossed the pier: their BOOTS were MUDDY.'],['Berto',"Berto studies the mud. ‘At least I don't have to wash the boots today!’"]],
 [['Parcel machine','The parcels come in three sizes. The machine only works in the right order.'],['Professor Muddle',"The Professor's hat is so big it could receive the post for him."],['Delivery sign','The sign shows: small → medium → large. The arrow gives the order of the parcels.'],['Ada','Ada is waiting for flour. A feathered hat is not a good substitute.']],
 [['Cloud machine','A light sail could pull this cloud. But it needs a rope to hold it!'],['Baron Topsy-Turvy',"The Baron has a huge hat. His idea of becoming important is even bigger."],['Coiled rope','A strong rope: it could hold something that flies.'],['Light cloth','Diamond-shaped cloth with two light sticks. It just needs a string.'],['Berto',"Berto is here to check the lighthouse's supplies."]]
 ];
 E.props.forEach((chapter,i)=>chapter.forEach((p,j)=>{add(p.name,props[i][j][0]);add(p.look,props[i][j][1]);}));
 const pairs=[
 ['Guarda','Look'],['Parla','Talk'],['Prendi','Take'],['Usa','Use'],['Guarda…','Look…'],['Parla con…','Talk to…'],['Prendi…','Take…'],['Usa…','Use…'],['Pettine','Comb'],['Chiave','Key'],['Forchetta','Fork'],['Sole','Sun'],['Luna','Moon'],['Stella','Star'],['Piccolo','Small'],['Medio','Medium'],['Grande','Large'],['Barca','Boat'],['Mare aperto','Open sea'],['nessuna','none'],['rossi','red'],['infangati','muddy'],['arancione','orange'],['viola','purple'],['verde','green'],
 ['Questo mistero è già risolto. Le stelle non si possono guadagnare due volte!','This mystery is already solved. You cannot earn the stars twice!'],[' Hai guadagnato 5 stelle!',' You earned 5 stars!'],['Questo reparto non è ancora stato costruito.','This department has not been built yet.'],['La sala radio riproduce lo spartito: Sole, Luna, Sole, Stella.','The radio plays the sheet music: Sun, Moon, Sun, Star.'],['Prima guarda lo spartito in piazza. La radio potrà riprodurlo tutte le volte che vuoi.','First look at the sheet music in the square. The radio can play it as often as you like.'],['Nessuna melodia da decifrare nel caso attuale. La radio è pronta per le prossime comunicazioni.','There is no melody to solve in this case. The radio is ready for new messages.'],['Scegli due colori diversi da mescolare.','Choose two different colours to mix.'],['Nel caso attuale non ci sono tre sospettati da confrontare.','There are no three suspects to compare in this case.'],['Il fascicolo è incompleto: cerca stoffa nel teatro e impronte al molo.','The file is incomplete: find cloth in the theatre and footprints at the pier.'],['Seleziona una scheda del sospettato.','Select a suspect file.'],['La scheda del Pirata corrisponde a entrambi gli indizi. Vai al teatro per chiedergli della corona.','The Pirate matches both clues. Go to the theatre and ask him about the crown.'],['Mago: gli stivali corrispondono, ma i guanti blu non sono quelli cercati.','Wizard: the boots match, but the blue gloves do not.'],['Giullare: i guanti corrispondono, ma gli stivali puliti non sono quelli cercati.','Jester: the gloves match, but the clean boots do not.'],['Puoi ordinare i pacchi durante il caso della posta.','You can sort the parcels during the postal case.'],['Pacco spostato. Quando sono piccolo, medio e grande puoi caricare il camion.','Parcel moved. When they are small, medium, large you can load the truck.'],['Non ci sono pacchi da consegnare nel caso attuale.','There are no parcels to deliver in this case.'],['Prima ordina i pacchi dal più piccolo al più grande.','First sort the parcels from smallest to largest.'],['I pacchi sono troppo grandi! Seleziona il Camion nel garage per caricarli.','The parcels are too big! Select the Truck in the garage to load them.'],['Camion caricato: Pippo consegna i pacchi al festival! ','Truck loaded: Pippo delivers the parcels to the festival! '],['L’aquilone serve per il caso del faro.','The kite is needed for the lighthouse case.'],['Il radar sarà utile per il caso del faro.','The radar will help with the lighthouse case.'],['Radar: il porto è occupato dalle barche; il faro deve restare visibile; il mare aperto è libero. Parti con l’elicottero e usa l’aquilone per spostare la nuvola.','Radar: boats are in the port; the lighthouse must stay visible; the open sea is clear. Fly by helicopter and use the kite to move the cloud.'],['Questo strumento non è disponibile qui.','This tool is not available here.'],['Non posso prenderlo. E non entra nemmeno nel taschino.','I cannot take that. It would not fit in my pocket anyway.'],['L’ho già preso.','I already took it.'],[' nelle tasche! Seleziona un oggetto, poi un altro per combinarli, oppure usalo nella scena.',' in my pockets! Select it, then another item to combine them, or use it in the scene.'],['Non vedo quell’oggetto qui.','I cannot see that object here.'],['Per combinare servono due oggetti diversi nelle tasche.','You need two different items in your pockets to combine them.'],['Una buona idea… per un altro mistero! Questi oggetti insieme non funzionano.','A good idea… for another mystery! These items do not work together.'],['Telo, stecche e corda: ho costruito un aquilone! Il vento farà il resto.','Cloth, sticks and rope: I made a kite! The wind will do the rest.'],['Il caso è già risolto. Nessun altro pasticcio per oggi!','The case is already solved. No more trouble today!'],['Prima scegli un oggetto nelle tasche.','First choose an item in your pockets.'],['Quell’oggetto non è in questo luogo.','That object is not in this place.'],['La serratura vuole il colore di un’arancia. Questo colore non va bene. Prova un’altra miscela!','The lock wants the colour of an orange. This colour is not right. Try another mixture!'],['L’aquilone è pronto! La macchina ha una domanda prima di lasciarlo partire.','The kite is ready! The machine has a question before letting it fly.'],['Non funziona così. Meglio guardare l’oggetto e ragionare su cosa gli manca.','That does not work. Look at the object and think about what it needs.'],['Questo enigma è già risolto.','This puzzle is already solved.'],['Per risolvere questo enigma devo raggiungere il luogo giusto.','I need to reach the right place to solve this puzzle.'],['Un pettine ha i denti, ma non apre le porte. Prova ancora!','A comb has teeth, but it cannot open doors. Try again!'],['Una forchetta può prendere gli spaghetti, ma non apre una serratura.','A fork can pick up spaghetti, but it cannot open a lock.'],['Berto: «Esatto! La chiave ha denti e apre le porte. Ecco quella del baule. Non usarla per pettinarti!»',"Berto: ‘Exactly! A key has teeth and opens doors. Here is the chest key. Do not comb your hair with it!’"],['Scegli uno dei tre tasti.','Choose one of the three keys.'],['Plonk! Non è la melodia giusta. Riparti dal primo simbolo: nessuna fretta.','Plonk! That is not the right melody. Start from the first symbol: take your time.'],['La nota è giusta! Continua la sequenza.','That note is right! Keep going.'],['Prima guarda entrambi gli indizi: la stoffa nel teatro e le impronte al molo.','First look at both clues: the cloth in the theatre and the footprints at the pier.'],['Il Giullare ha guanti rossi, ma i suoi stivali sono puliti. Non corrisponde a entrambi gli indizi.','The Jester has red gloves, but clean boots. He does not match both clues.'],['Il Mago ha stivali sporchi, ma i suoi guanti sono blu. Servono entrambi gli indizi!','The Wizard has muddy boots, but blue gloves. Both clues must match!'],['La macchina fa PUF! Serve l’ordine dal più piccolo al più grande. Puoi spostare ancora i pacchi.','The machine goes POOF! It needs smallest to largest. You can keep moving the parcels.'],['Serve il Camion per trasportare i pacchi. Selezionalo nel garage: l’ordine dei pacchi resterà salvato.','You need the Truck to carry the parcels. Select it in the garage: the parcel order will be saved.'],['Pacco spostato di un posto verso sinistra.','Parcel moved one place to the left.'],['Il primo pacco è già tutto a sinistra.','The first parcel is already on the far left.'],['La barca naviga nell’acqua: cerchiamo qualcosa che vola tenuto da un filo.','A boat sails on water: we need something that flies on a string.'],['L’elicottero ha un motore. L’indovinello parla di un oggetto senza motore.','A helicopter has an engine. The riddle describes something without an engine.'],['Esatto: l’aquilone! Ora scegli dove portare la nuvola.','Exactly: a kite! Now choose where to take the cloud.'],['Al porto ci sono le barche! La nuvola deve andare dove non copre né barche né faro.','There are boats in the port! The cloud must not hide the boats or the lighthouse.'],['Sul faro la nuvola nasconderebbe ancora la luce. Dove c’è spazio libero?','Over the lighthouse, the cloud would still hide the light. Where is there free space?'],['Questo enigma non è disponibile in questo capitolo.','This puzzle is not available in this chapter.']
 ];
 pairs.forEach(([it,en])=>add(it,en));
 root.PippoEnglish=dict;
})(globalThis);
